39	#define csr_read(csr) ({                        \
40		size_t __r;	               		            \
41		__asm__ volatile ("csrr %0, %1" : "=r" (__r) : "i" (csr)); \
42		__r;							            \
43	})
44	
45	// Non-volatile CSR read: for CSRs that are constant over the reader's lifetime
46	// (e.g. CTA identity/dimension), so the compiler may CSE/hoist them out of loops.
47	// Use csr_read (volatile) for CSRs that change across reads, e.g. mcycle.
48	#define csr_read_nv(csr) ({                     \
49		size_t __r;	               		            \
50		__asm__ ("csrr %0, %1" : "=r" (__r) : "i" (csr)); \
51		__r;							            \
52	})
53	
54	#define csr_write(csr, val)	({                  \
55		size_t __v = (size_t)(val);                 \
56		if (__builtin_constant_p(val) && __v < 32)  \
57	        __asm__ volatile ("csrwi %0, %1" :: "i" (csr), "i" (__v));  \
58	    else                                        \
59	        __asm__ volatile ("csrw %0, %1"	:: "i" (csr), "r" (__v));  \
60	})
61	
62	#define csr_swap(csr, val) ({                   \
63	    size_t __r;                                 \
64		size_t __v = (size_t)(val);	                \
65		if (__builtin_constant_p(val) && __v < 32)  \
66	        __asm__ volatile ("csrrwi %0, %1, %2" : "=r" (__r) : "i" (csr), "i" (__v)); \
67	    else                                        \
68	        __asm__ volatile ("csrrw %0, %1, %2" : "=r" (__r) : "i" (csr), "r" (__v)); \
69		__r;						                \
70	})
71	
72	#define csr_read_set(csr, val) ({               \
73		size_t __r;                                 \
74		size_t __v = (size_t)(val);	                \
75	    if (__builtin_constant_p(val) && __v < 32)  \
76		    __asm__ volatile ("csrrsi %0, %1, %2" : "=r" (__r) : "i" (csr), "i" (__v)); \
77	    else                                        \
78	        __asm__ volatile ("csrrs %0, %1, %2" : "=r" (__r) : "i" (csr), "r" (__v)); \
79		__r;							            \
80	})
81	
82	#define csr_set(csr, val) ({                    \
83		size_t __v = (size_t)(val);	                \
84	    if (__builtin_constant_p(val) && __v < 32)  \
85		    __asm__ volatile ("csrsi %0, %1" :: "i" (csr), "i" (__v));  \
86	    else                                        \
87	        __asm__ volatile ("csrs %0, %1"	:: "i" (csr), "r" (__v));  \
88	})
89	
90	#define csr_read_clear(csr, val) ({             \
91		size_t __r;                                 \
92		size_t __v = (size_t)(val);	                \
93	    if (__builtin_constant_p(val) && __v < 32)  \
94		    __asm__ volatile ("csrrci %0, %1, %2" : "=r" (__r) : "i" (csr), "i" (__v)); \
95	    else                                        \
96	        __asm__ volatile ("csrrc %0, %1, %2" : "=r" (__r) : "i" (csr), "r" (__v)); \
97		__r;							            \
98	})
99	
100	#define csr_clear(csr, val)	({                  \
101		size_t __v = (size_t)(val);                 \
102		if (__builtin_constant_p(val) && __v < 32)  \
103	        __asm__ volatile ("csrci %0, %1" :: "i" (csr), "i" (__v)); \
104	    else                                        \
105	        __asm__ volatile ("csrc %0, %1"	:: "i" (csr), "r" (__v)); \
106	})
