226	// Return current cycle counter
227	inline uint64_t vx_rdcycle() {
228	#if __riscv_xlen == 64
229	    return csr_read(VX_CSR_MCYCLE);
230	#elif __riscv_xlen == 32
231	    uint32_t hi0, lo, hi1;
232	    do {
233	        hi0 = csr_read(VX_CSR_MCYCLE_H);
234	        lo  = csr_read(VX_CSR_MCYCLE);
235	        hi1 = csr_read(VX_CSR_MCYCLE_H);
236	    } while (hi0 != hi1);
237	    return (((uint64_t)hi0) << 32) | lo;
238	#else
239	#error "Unsupported RISC-V XLEN"
240	#endif
241	}
