249	/* Safely flushes the warp pipeline and reads the 64-bit cycle counter.
250	 * Automatically handles 32-bit overflow mitigation or native 64-bit reads.
251	 */
252	static inline uint64_t vx_rdcycle_sync() {
253	    uint64_t cycles;
254	#if __riscv_xlen == 32
255	    uint32_t cycle_lo, cycle_hi, cycle_hi_check;
256	    __asm__ volatile (
257	        ".insn r %3, 7, 0, x0, x0, x0\n\t"
258	        "1:\n\t"
259	        "csrr %0, %4\n\t"
260	        "csrr %1, %5\n\t"
261	        "csrr %2, %4\n\t"
262	        "bne %0, %2, 1b\n\t"
263	        : "=&r" (cycle_hi), "=&r" (cycle_lo), "=&r" (cycle_hi_check)
264	        : "i" (RISCV_CUSTOM0), "i" (VX_CSR_MCYCLE_H), "i" (VX_CSR_MCYCLE)
265	        : "memory"
266	    );
267	    cycles = ((uint64_t)cycle_hi << 32) | cycle_lo;
268	#elif __riscv_xlen == 64
269	    __asm__ volatile (
270	        ".insn r %1, 7, 0, x0, x0, x0\n\t"
271	        "csrr %0, %2\n\t"
272	        : "=r" (cycles)
273	        : "i" (RISCV_CUSTOM0), "i" (VX_CSR_MCYCLE)
274	        : "memory"
275	    );
276	#else
277	#error "Unsupported RISC-V XLEN"
278	#endif
279	
280	    return cycles;
281	}
282	
283	typedef struct {
284	    uint32_t hi;
285	    uint32_t lo;
286	} __rdcycle_time;
287	
288	static inline __attribute__((always_inline)) __rdcycle_time vx_rdcycle_sync_begin(void) {
289	    __rdcycle_time t;
290	#if __riscv_xlen == 32
291	    __asm__ volatile (
292	        ".insn r %2, 7, 0, x0, x0, x0\n\t"
293	        "csrr %0, %3\n\t"
294	        "csrr %1, %4\n\t"
295	        : "=r" (t.hi), "=r" (t.lo)
296	        : "i" (RISCV_CUSTOM0), "i" (VX_CSR_MCYCLE_H), "i" (VX_CSR_MCYCLE)
297	        : "memory"
298	    );
299	#elif __riscv_xlen == 64
300	    uint64_t cycles;
301	    __asm__ volatile (
302	        ".insn r %1, 7, 0, x0, x0, x0\n\t"
303	        "csrr %0, %2\n\t"
304	        : "=r" (cycles)
305	        : "i" (RISCV_CUSTOM0), "i" (VX_CSR_MCYCLE)
306	        : "memory"
307	    );
308	    t.hi = (uint32_t)(cycles >> 32);
309	    t.lo = (uint32_t)cycles;
310	#else
311	#error "Unsupported RISC-V XLEN"
312	#endif
313	    return t;
314	}
315	
316	static inline __attribute__((always_inline)) __rdcycle_time vx_rdcycle_sync_end(void) {
317	    __rdcycle_time t;
318	#if __riscv_xlen == 32
319	    __asm__ volatile (
320	        ".insn r %2, 7, 0, x0, x0, x0\n\t"
321	        "csrr %0, %3\n\t"
322	        "csrr %1, %4\n\t"
323	        : "=r" (t.lo), "=r" (t.hi)
324	        : "i" (RISCV_CUSTOM0), "i" (VX_CSR_MCYCLE), "i" (VX_CSR_MCYCLE_H)
325	        : "memory"
326	    );
327	#elif __riscv_xlen == 64
328	    uint64_t cycles;
329	    __asm__ volatile (
330	        ".insn r %1, 7, 0, x0, x0, x0\n\t"
331	        "csrr %0, %2\n\t"
332	        : "=r" (cycles)
333	        : "i" (RISCV_CUSTOM0), "i" (VX_CSR_MCYCLE)
334	        : "memory"
335	    );
336	    t.hi = (uint32_t)(cycles >> 32);
337	    t.lo = (uint32_t)cycles;
338	#else
339	#error "Unsupported RISC-V XLEN"
340	#endif
341	    return t;
342	}
