344	static inline __attribute__((always_inline)) uint64_t vx_rdcycle_sync_diff(__rdcycle_time start, __rdcycle_time end) {
345	#if __riscv_xlen == 32
346	    uint32_t diff_hi = end.hi;
347	    uint32_t diff_lo = end.lo;
348	    uint32_t tmp = start.hi;
349	    uint32_t start_lo = start.lo;
350	
351	    __asm__ volatile (
352	        "sub  %0, %0, %2\n\t"
353	        "sltu %2, %1, %3\n\t"
354	        "sub  %1, %1, %3\n\t"
355	        "sub  %0, %0, %2\n\t"
356	        : "+r" (diff_hi), "+r" (diff_lo), "+r" (tmp)
357	        : "r" (start_lo)
358	        : "memory"
359	    );
360	
361	    return ((uint64_t)diff_hi << 32) | diff_lo;
362	#elif __riscv_xlen == 64
363	    uint64_t s = ((uint64_t)start.hi << 32) | start.lo;
364	    uint64_t e = ((uint64_t)end.hi << 32) | end.lo;
365	    return e - s;
366	#else
367	#error "Unsupported RISC-V XLEN"
368	#endif
369	}
