409	// Shift values up by b lanes within each sub-group; out-of-range lanes keep their own value.
410	inline __attribute__((const)) size_t vx_shfl_up(size_t value, int bval, int cval, int mask) {
411	    size_t ret;
412	    int bc = (mask << 12) | (cval << 6) | bval;
413	    __asm__ volatile (".insn r %1, 4, 1, %0, %2, %3" : "=r"(ret) : "i"(RISCV_CUSTOM0), "r"(value), "r"(bc));
414	    return ret;
415	}
