417	// Shift values down by b lanes within each sub-group; out-of-range lanes keep their own value.
418	inline __attribute__((const)) size_t vx_shfl_down(size_t value, int bval, int cval, int mask) {
419	    size_t ret;
420	    int bc = (mask << 12) | (cval << 6) | bval;
421	    __asm__ volatile (".insn r %1, 5, 1, %0, %2, %3" : "=r"(ret) : "i"(RISCV_CUSTOM0), "r"(value), "r"(bc));
422	    return ret;
423	}
