425	// “Butterfly” exchange using XOR with b as a bit‐mask: each lane swaps with lane ⊕ b.
426	inline __attribute__((const)) size_t vx_shfl_bfly(size_t value, int bval, int cval, int mask) {
427	    size_t ret;
428	    int bc = (mask << 12) | (cval << 6) | bval;
429	    __asm__ volatile (".insn r %1, 6, 1, %0, %2, %3" : "=r"(ret) : "i"(RISCV_CUSTOM0), "r"(value), "r"(bc));
430	    return ret;
431	}
