433	// Gather from an explicit index: every lane reads the value from base + idx, where idx = b[i].
434	inline __attribute__((const)) size_t vx_shfl_idx(size_t value, int bval, int cval, int mask) {
435	    size_t ret;
436	    int bc = (mask << 12) | (cval << 6) | bval;
437	    __asm__ volatile (".insn r %1, 7, 1, %0, %2, %3" : "=r"(ret) : "i"(RISCV_CUSTOM0), "r"(value), "r"(bc));
438	    return ret;
