441	//
442	// Warp-Level Lane Gather Extension
443	//
444	
445	// Each lane gathers a value from the source lane's register file.
446	// S = source lane (compile-time constant, 0-3).
447	// The source lane retains its own rd value; lane (S+1) gets v1[S], (S+2) gets v2[S], (S+3) gets v3[S].
448	#define __VX_WGATHER(src_lane, self_val, v1, v2, v3) ({ \
449	    size_t __ret = (self_val);                          \
450	    __asm__ volatile (                                  \
451	        ".insn r4 %1, 0, %2, %0, %3, %4, %5"            \
452	        : "+r"(__ret)                                   \
453	        : "i"(RISCV_CUSTOM1), "i"(src_lane),            \
454	          "r"(v1), "r"(v2), "r"(v3)                     \
455	    );                                                  \
456	    __ret;                                              \
457	})
458	
459	// Warp-level gather with source lane 0.
460	inline __attribute__((const)) size_t
461	vx_wgather(size_t self_val, size_t v1, size_t v2, size_t v3) {
462	    return __VX_WGATHER(0, self_val, v1, v2, v3);
463	}
464	
465	// Warp-level gather with an explicit (compile-time constant) source lane.
466	#define vx_wgather_from(src_lane, self_val, v1, v2, v3) \
467	    __VX_WGATHER(src_lane, self_val, v1, v2, v3)
468	
469	// Transpose a 4×4 matrix distributed one row per lane, using 4 wgather instructions.
470	//
471	// Each lane i must hold one complete row of the matrix in four registers:
472	//   a0[i] = M[i][0],  a1[i] = M[i][1],  a2[i] = M[i][2],  a3[i] = M[i][3]
473	//
474	// After the macro, each lane i holds column i:
475	//   out0[i] = M[0][i],  out1[i] = M[1][i],  out2[i] = M[2][i],  out3[i] = M[3][i]
476	//
477	// Operates within each independent group of 4 lanes (scalable to any NUM_LANES).
478	// out0..out3 must be distinct lvalues from a0..a3 (not in-place safe).
479	#define vx_transpose4(a0, a1, a2, a3, out0, out1, out2, out3) do { \
480	    (out0) = vx_wgather_from(0, (a0), (a1), (a2), (a3));           \
481	    (out1) = vx_wgather_from(1, (a1), (a2), (a3), (a0));           \
482	    (out2) = vx_wgather_from(2, (a2), (a3), (a0), (a1));           \
483	    (out3) = vx_wgather_from(3, (a3), (a0), (a1), (a2));           \
484	} while (0)
485	
486	//
487	// Asynchronous Barrier extensions
488	//
489	
490	// Async Barrier Arrive: non-blocking, returns a phase (generation number)
491	// barrier_id: identifier of the barrier
492	// num_warps: number of warps participating in the barrier
493	// returns: number representing the barrier phase for this arrive
494	inline int vx_barrier_arrive(int barrier_id, int num_warps) {
495	    int phase;
496	    __asm__ volatile (
497	        ".insn r %1, 6, 0, %0, %2, %3" : "=r"(phase) : "i"(RISCV_CUSTOM0), "r"(barrier_id), "r"(num_warps) : "memory"
498	    );
499	    return phase;
500	}
501	
502	// Async Barrier Wait: blocks until a barrier phase is complete
503	// barrier_id: identifier of the barrier
504	// phase: the phase returned by vx_barrier_arrive
505	inline void vx_barrier_wait(int barrier_id, int phase) {
506	    __asm__ volatile (
507	        ".insn r %0, 6, 0, x0, %1, %2" :: "i"(RISCV_CUSTOM0), "r"(barrier_id), "r"(phase) : "memory"
508	    );
509	}
510	
511	// Async Transaction Expect: pre-register N pending transaction events on
512	// the given barrier. Reuses the barrier_arrive opcode but encodes rs2[31]=1
513	// to flag expect-tx semantics. The lower bits of rs2 carry the count N.
514	// Each pending event must be matched by a future release (e.g. DXA SMEM
515	// completion). The barrier only flips phase when both arrive_count==0 AND
516	// events==0.
517	//
518	// NOTE: rd must be non-x0 — decode uses (rd != 0) to distinguish arrive
519	// vs wait on this opcode. The returned phase is meaningless for expect_tx
520	// (we don't advance arrival count) but we keep a real register destination
521	// to satisfy the decoder.
522	inline void vx_barrier_expect_tx(int barrier_id, int count) {
523	    int discard;
524	    int rs2 = count | 0x80000000;
525	    __asm__ volatile (
526	        ".insn r %1, 6, 0, %0, %2, %3" : "=r"(discard) : "i"(RISCV_CUSTOM0), "r"(barrier_id), "r"(rs2) : "memory"
527	    );
528	    (void)discard;
529	}
530	
531	//
532	// Load Bytes Packing Extension
533	//
534	
535	// Packed-load 4 bytes into one FP register bit-container.
536	// base: pointer to the first byte to load
537	// stride: byte offset between consecutive bytes to load
538	// fd = bitcast<float>((MEM8[base + 0 * stride] << 0)
539	//                   | (MEM8[base + 1 * stride] << 8)
540	//                   | (MEM8[base + 2 * stride] << 16)
541	//                   | (MEM8[base + 3 * stride] << 24));
542	__attribute__((always_inline))
543	inline float vx_packlb_f(const void* base, uint32_t stride) {
544	    float out;
545	    __asm__ volatile (
546	        ".insn r %1, 1, 4, %0, %2, %3" : "=f"(out) : "i"(RISCV_CUSTOM0), "r"(base), "r"(stride) : "memory"
547	    );
548	    return out;
549	}
550	
551	// Packed-load 2 halfwords into one FP register bit-container.
552	// base: pointer to the first halfword to load
553	// stride: byte offset between consecutive halfwords to load
554	// fd = bitcast<float>((MEM16[base + 0 * stride] << 0)
555	//                   | (MEM16[base + 1 * stride] << 16));
556	__attribute__((always_inline))
557	inline float vx_packlh_f(const void* base, uint32_t stride) {
558	    float out;
559	    __asm__ volatile (
560	        ".insn r %1, 2, 4, %0, %2, %3" : "=f"(out) : "i"(RISCV_CUSTOM0), "r"(base), "r"(stride) : "memory"
561	    );
562	    return out;
563	}
564	
565	#ifdef __cplusplus
566	}
567	#endif
568	
569	#endif // __VX_INTRINSICS_H__
570

