#ifndef __VX_SPAWN_H__
#define __VX_SPAWN_H__

#include <vx_intrinsics.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef union {
  struct {
    uint32_t x;
    uint32_t y;
    uint32_t z;
  };
  uint32_t m[3];
} dim3_t;

extern __thread dim3_t blockIdx;
extern __thread dim3_t threadIdx;
extern dim3_t gridDim;
extern dim3_t blockDim;

extern __thread uint32_t __local_group_id;
extern __thread uint32_t __sub_group_id;
extern uint32_t __warps_per_group;

typedef void (*vx_kernel_func_cb)(void *arg);

typedef void (*vx_serial_cb)(void *arg);

static inline __attribute__((always_inline)) uint32_t get_local_group_id() {
  uint32_t __UNIFORM__ v = __local_group_id;
  return v;
}

static inline __attribute__((always_inline)) uint32_t get_sub_group_id() {
  uint32_t __UNIFORM__ v = __sub_group_id;
  return v;
}

static inline __attribute__((always_inline)) uint32_t get_num_sub_groups() {
  uint32_t __UNIFORM__ v = __warps_per_group;
  return v;
}


#define __local_mem(size) \
  (void*)((int8_t*)csr_read(VX_CSR_LOCAL_MEM_BASE) + get_local_group_id() * size)

#define __syncthreads() \
  vx_barrier(get_local_group_id(), get_num_sub_groups())

// launch a kernel function with a grid of blocks and block of threads
int vx_spawn_threads(uint32_t dimension,
                     const uint32_t* grid_dim,
                     const uint32_t* block_dim,
                     vx_kernel_func_cb kernel_func,
                     const void* arg);

// function call serialization
void vx_serial(vx_serial_cb callback, const void * arg);

#ifdef __cplusplus
}
#endif

#endif // __VX_SPAWN_H__

