13	
14	#include <vx_spawn.h>
15	#include <vx_intrinsics.h>
16	#include <vx_print.h>
17	
18	#ifdef __cplusplus
19	extern "C" {
20	#endif
21	
22	#ifndef MIN
23	#define MIN(a, b) ((a) < (b) ? (a) : (b))
24	#endif
25	
26	__thread dim3_t blockIdx;
27	__thread dim3_t threadIdx;
28	dim3_t gridDim;
29	dim3_t blockDim;
30	
31	__thread uint32_t __local_group_id;
32	__thread uint32_t __sub_group_id;
33	uint32_t __warps_per_group;
34	
35	typedef struct {
36		vx_kernel_func_cb callback;
37		const void* arg;
38		uint32_t group_offset;
39		uint32_t warp_batches;
40		uint32_t remaining_warps;
41	  uint32_t warps_per_group;
42	  uint32_t groups_per_core;
43	  uint32_t remaining_mask;
44	} wspawn_groups_args_t;
45	
46	typedef struct {
47		vx_kernel_func_cb callback;
48		const void* arg;
49		uint32_t all_tasks_offset;
50	  uint32_t remain_tasks_offset;
51		uint32_t warp_batches;
52		uint32_t remaining_warps;
53	} wspawn_threads_args_t;
54	
55	static void __attribute__ ((noinline)) process_threads() {
56	  wspawn_threads_args_t* targs = (wspawn_threads_args_t*)csr_read(VX_CSR_MSCRATCH);
57	
58	  uint32_t threads_per_warp = vx_num_threads();
59	  uint32_t warp_id = vx_warp_id();
60	  uint32_t thread_id = vx_thread_id();
61	
62	  uint32_t remaining_warps = targs->remaining_warps;
63	  uint32_t warp_batches = targs->warp_batches;
64	
65	  uint32_t start_warp_add = (warp_id < remaining_warps) ? warp_id : remaining_warps;
66	  uint32_t start_warp = warp_id * warp_batches + start_warp_add;
67	  uint32_t iterations = warp_batches + (warp_id < remaining_warps);
68	
69	  uint32_t start_task_id = targs->all_tasks_offset + start_warp * threads_per_warp + thread_id;
70	  uint32_t end_task_id = start_task_id + iterations * threads_per_warp;
71	
72	  uint32_t gridDim_x = gridDim.x;
73	  uint32_t gridDim_y = gridDim.y;
74	
75	  vx_kernel_func_cb callback = targs->callback;
76	  const void* arg = targs->arg;
77	
78	  for (uint32_t task_id = start_task_id; task_id < end_task_id; task_id += threads_per_warp) {
79	    blockIdx.x = task_id % gridDim_x;
80	    blockIdx.y = (task_id / gridDim_x) % gridDim_y;
81	    blockIdx.z = task_id / (gridDim_x * gridDim_y);
82	    callback((void*)arg);
83	  }
84	}
85	
86	static void __attribute__ ((noinline)) process_remaining_threads() {
87	  wspawn_threads_args_t* targs = (wspawn_threads_args_t*)csr_read(VX_CSR_MSCRATCH);
88	
89	  uint32_t thread_id = vx_thread_id();
90	  uint32_t task_id = targs->remain_tasks_offset + thread_id;
91	  blockIdx.x = task_id % gridDim.x;
92	  blockIdx.y = (task_id / gridDim.x) % gridDim.y;
93	  blockIdx.z = task_id / (gridDim.x * gridDim.y);
94	  (targs->callback)((void*)targs->arg);
95	}
96	
97	static void __attribute__ ((noinline)) process_threads_stub() {
98	  // activate all threads
99	  vx_tmc(-1);
100	  process_threads();
101	  // disable warp
102	  vx_tmc_zero();
103	}
104	
105	///////////////////////////////////////////////////////////////////////////////
106	
107	static void __attribute__ ((noinline)) process_thread_groups() {
108	  wspawn_groups_args_t* targs = (wspawn_groups_args_t*)csr_read(VX_CSR_MSCRATCH);
109	
110	  uint32_t threads_per_warp = vx_num_threads();
111	  uint32_t warp_id = vx_warp_id();
112	  uint32_t thread_id = vx_thread_id();
113	  uint32_t warps_per_group = targs->warps_per_group;
114	  uint32_t groups_per_core = targs->groups_per_core;
115	  uint32_t remaining_warps = targs->remaining_warps;
116	  uint32_t warp_batches = targs->warp_batches;
117	
118	  uint32_t blockDim_x = blockDim.x;
119	  uint32_t blockDim_y = blockDim.y;
120	  uint32_t blockDim_xy = blockDim_x * blockDim_y;
121	  uint32_t gridDim_x = gridDim.x;
122	  uint32_t gridDim_y = gridDim.y;
123	  uint32_t gridDim_xy = gridDim_x * gridDim_y;
124	
125	  uint32_t iterations = warp_batches + (warp_id < remaining_warps);
126	
127	  uint32_t local_group_id = warp_id / warps_per_group;
128	  uint32_t group_warp_id = warp_id - local_group_id * warps_per_group;
129	  uint32_t local_task_id = group_warp_id * threads_per_warp + thread_id;
130	
131	  __local_group_id = local_group_id;
132	  __sub_group_id = group_warp_id;
133	  threadIdx.x = local_task_id % blockDim_x;
134	  threadIdx.y = (local_task_id / blockDim_x) % blockDim_y;
135	  threadIdx.z = local_task_id / blockDim_xy;
136	
137	  uint32_t start_group = targs->group_offset + local_group_id;
138	  uint32_t group_stride = groups_per_core;
139	  uint32_t end_group = start_group + iterations * group_stride;
140	
141	  vx_kernel_func_cb callback = targs->callback;
142	  const void* arg = targs->arg;
143	
144	  for (uint32_t group_id = start_group; group_id < end_group; group_id += group_stride) {
145	    blockIdx.x = group_id % gridDim_x;
146	    blockIdx.y = (group_id / gridDim_x) % gridDim_y;
147	    blockIdx.z = group_id / (gridDim_x * gridDim_y);
148	    callback((void*)arg);
149	  }
150	}
151	
152	static void __attribute__ ((noinline)) process_thread_groups_stub() {
153	  wspawn_groups_args_t* targs = (wspawn_groups_args_t*)csr_read(VX_CSR_MSCRATCH);
154	  uint32_t warps_per_group = targs->warps_per_group;
155	  uint32_t remaining_mask = targs->remaining_mask;
156	  uint32_t warp_id = vx_warp_id();
157	  uint32_t group_warp_id = warp_id % warps_per_group;
158	  uint32_t threads_mask = (group_warp_id == warps_per_group-1) ? remaining_mask : -1;
159	
160	  // activate threads
161	  vx_tmc(threads_mask);
162	  process_thread_groups();
163	  // disable all warps except warp0
164	  vx_tmc(0 == vx_warp_id());
165	}
166	
167	///////////////////////////////////////////////////////////////////////////////
168	
169	int vx_spawn_threads(uint32_t dimension,
170	                     const uint32_t* grid_dim,
171	                     const uint32_t * block_dim,
172	                     vx_kernel_func_cb kernel_func,
173	                     const void* arg) {
174	  // calculate number of groups and group size
175	  uint32_t num_groups = 1;
176	  uint32_t group_size = 1;
177	  for (uint32_t i = 0; i < 3; ++i) {
178	    uint32_t gd = (grid_dim && (i < dimension)) ? grid_dim[i] : 1;
179	    uint32_t bd = (block_dim && (i < dimension)) ? block_dim[i] : 1;
180	    num_groups *= gd;
181	    group_size *= bd;
182	    gridDim.m[i] = gd;
183	    blockDim.m[i] = bd;
184	  }
185	
186	  // device specifications
187	  uint32_t num_cores = vx_num_cores();
188	  uint32_t warps_per_core = vx_num_warps();
189	  uint32_t threads_per_warp = vx_num_threads();
190	  uint32_t core_id = vx_core_id();
191	
192	  // check group size
193	  uint32_t threads_per_core = warps_per_core * threads_per_warp;
194	  if (threads_per_core < group_size) {
195	    vx_printf("error: group_size > threads_per_core (%d,%d)\n", group_size, threads_per_core);
196	    return -1;
197	  }
198	
199	  if (group_size > 1) {
200	    // calculate number of warps per group
201	    uint32_t warps_per_group = group_size / threads_per_warp;
202	    uint32_t remaining_threads = group_size - warps_per_group * threads_per_warp;
203	    uint32_t remaining_mask = -1;
204	    if (remaining_threads != 0) {
205	      remaining_mask = (1 << remaining_threads) - 1;
206	      ++warps_per_group;
207	    }
208	
209	    // calculate necessary active cores
210	    uint32_t needed_warps = num_groups * warps_per_group;
211	    uint32_t needed_cores = (needed_warps + warps_per_core-1) / warps_per_core;
212	    uint32_t active_cores = MIN(needed_cores, num_cores);
213	
214	    // only active cores participate
215	    if (core_id >= active_cores)
216	      return 0;
217	
218	    // total number of groups per core
219	    uint32_t total_groups_per_core = num_groups / active_cores;
220	    uint32_t remaining_groups_per_core = num_groups - active_cores * total_groups_per_core;
221	    if (core_id < remaining_groups_per_core)
222	      ++total_groups_per_core;
223	
224	    // calculate number of warps to activate
225	    uint32_t groups_per_core = warps_per_core / warps_per_group;
226	    uint32_t total_warps_per_core = total_groups_per_core * warps_per_group;
227	    uint32_t active_warps = total_warps_per_core;
228	    uint32_t warp_batches = 1, remaining_warps = 0;
229	    if (active_warps > warps_per_core) {
230	      active_warps = groups_per_core * warps_per_group;
231	      warp_batches = total_warps_per_core / active_warps;
232	      remaining_warps = total_warps_per_core - warp_batches * active_warps;
233	    }
234	
235	    // calculate offsets for group distribution
236	    uint32_t group_offset;
237	    if (core_id < remaining_groups_per_core) {
238	      group_offset = core_id * total_groups_per_core;
239	    } else {
240	      group_offset = remaining_groups_per_core + core_id * total_groups_per_core;
241	    }
242	
243	    // set scheduler arguments
244	    wspawn_groups_args_t wspawn_args = {
245	      kernel_func,
246	      arg,
247	      group_offset,
248	      warp_batches,
249	      remaining_warps,
250	      warps_per_group,
251	      groups_per_core,
252	      remaining_mask
253	    };
254	    csr_write(VX_CSR_MSCRATCH, &wspawn_args);
255	
256	    __warps_per_group = warps_per_group;
257	    // execute callback on other warps
258	    vx_wspawn(active_warps, process_thread_groups_stub);
259	    // execute callback on warp0
260	    process_thread_groups_stub();
261	  } else {
262	    // set constant workitem attributes
263	    __warps_per_group = 0;
264	    __local_group_id = 0;
265	    __sub_group_id = 0;
266	    threadIdx.x = 0;
267	    threadIdx.y = 0;
268	    threadIdx.z = 0;
269	
270	    uint32_t num_tasks = num_groups;
271	
272	    // calculate necessary active cores
273	    uint32_t needed_cores = (num_tasks + threads_per_core - 1) / threads_per_core;
274	    uint32_t active_cores = MIN(needed_cores, num_cores);
275	
276	    // only active cores participate
277	    if (core_id >= active_cores)
278	      return 0;
279	
280	    // number of tasks per core
281	    uint32_t tasks_per_core = num_tasks / active_cores;
282	    uint32_t remaining_tasks_per_core = num_tasks - tasks_per_core * active_cores;
283	    if (core_id < remaining_tasks_per_core)
284	      ++tasks_per_core;
285	
286	    // calculate number of warps to activate
287	    uint32_t total_warps_per_core = tasks_per_core / threads_per_warp;
288	    uint32_t remaining_tasks = tasks_per_core - total_warps_per_core * threads_per_warp;
289	    uint32_t active_warps = total_warps_per_core;
290	    uint32_t warp_batches = 1, remaining_warps = 0;
291	    if (active_warps > warps_per_core) {
292	      active_warps = warps_per_core;
293	      warp_batches = total_warps_per_core / active_warps;
294	      remaining_warps = total_warps_per_core - warp_batches * active_warps;
295	    }
296	
297	    // calculate offsets for task distribution
298	    uint32_t all_tasks_offset;
299	    if (core_id < remaining_tasks_per_core) {
300	      all_tasks_offset = core_id * tasks_per_core;
301	    } else {
302	      all_tasks_offset = remaining_tasks_per_core + core_id * tasks_per_core;
303	    }
304	    uint32_t remain_tasks_offset = all_tasks_offset + (tasks_per_core - remaining_tasks);
305	
306	    // prepare scheduler arguments
307	    wspawn_threads_args_t wspawn_args = {
308	      kernel_func,
309	      arg,
310	      all_tasks_offset,
311	      remain_tasks_offset,
312	      warp_batches,
313	      remaining_warps
314	    };
315	    csr_write(VX_CSR_MSCRATCH, &wspawn_args);
316	
317	    if (active_warps >= 1) {
318	      // execute callback on other warps
319	      vx_wspawn(active_warps, process_threads_stub);
320	      // activate all threads
321	      vx_tmc(-1);
322	      process_threads();
323	      // back to single-threaded
324	      vx_tmc_one();
325	    }
326	
